<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import AddAccountDialog from './components/AddAccountDialog.vue'
import AccountLifecycleDialog from './components/AccountLifecycleDialog.vue'
import ManualAddDialog from './components/ManualAddDialog.vue'
import QRLoginDialog from './components/QRLoginDialog.vue'
import AccountProfileModal from './components/AccountProfileModal.vue'
import AccountBatchDialog from './components/AccountBatchDialog.vue'
import DeleteConfirmDialog from './components/DeleteConfirmDialog.vue'
import { exportAccountRisks, getAccountGroups, getAccountMatrixDetail, getAccountMatrixSummary, getAccountProfileSync, queryAccountMatrix, replaceAccountGroupMembers, saveAccountGroup, syncAccountProfile, syncAccountRisks, newRequestId, type AccountBatchSelectionMode, type AccountGroup, type AccountMatrixSummary, type MatrixAccount } from '@/api/matrix'
import { showError, showSuccess } from '@/utils'
import { hasPermission } from '@/utils/permission'
import { useModalFocusTrap } from '@/composables/useModalFocusTrap'

const route=useRoute(),router=useRouter()
const loading=ref(false),summary=ref<AccountMatrixSummary|null>(null),accounts=ref<MatrixAccount[]>([]),allAccounts=ref<MatrixAccount[]>([]),groups=ref<AccountGroup[]>([]),total=ref(0),page=ref(1)
const lifecycleTarget=ref<MatrixAccount|null>(null),editTarget=ref<MatrixAccount|null>(null)
const filter=reactive({lifecycleState:'',search:'',connectionStatus:'',riskSeverity:'',groupId:undefined as number|undefined})
const selected=ref<MatrixAccount|null>(null),detailLoading=ref(false),showQr=ref(false),showManual=ref(false),showEdit=ref(false)
const profileSyncing=ref(false)
const riskSyncing=ref(false)
let profileSyncRun=0
const cancelProfilePolling=()=>{profileSyncRun++;profileSyncing.value=false}
const showBatch=ref(false),selectionMode=ref<AccountBatchSelectionMode>('EXPLICIT'),selectedIds=ref<number[]>([]),excludedIds=ref<number[]>([])
const detailOpen = computed({
  get: () => Boolean(selected.value),
  set: (value: boolean) => {
    if (!value) {
      cancelProfilePolling()
      selected.value = null
      void router.replace({ query: { ...route.query, accountId: undefined } })
    }
  },
})
const groupDialog=ref(false),groupSaving=ref(false),groupForm=reactive({id:undefined as number|undefined,groupName:'',color:'#ffda44',description:'',accountIds:[] as number[]})
const deleteTarget=ref<MatrixAccount|null>(null),deleteFeedback=ref('')
const openDelete=(account:MatrixAccount)=>{deleteTarget.value=account}
const deleted=async()=>{const target=deleteTarget.value;if(selected.value?.accountId===target?.accountId)closeDetail();clearSelection();deleteFeedback.value='本系统空账号已删除，历史审计记录保留。';await load()}
useModalFocusTrap(groupDialog,()=>document.querySelector<HTMLElement>('.account-matrix .modal-card'))
useModalFocusTrap(detailOpen,()=>document.querySelector<HTMLElement>('.account-matrix .profile-dialog'))
const totalPages=computed(()=>Math.max(1,Math.ceil(total.value/20)))
const selectionCount=computed(()=>selectionMode.value==='FILTER_SNAPSHOT'?Math.max(0,total.value-excludedIds.value.length):selectedIds.value.length)
const pageAllSelected=computed(()=>accounts.value.length>0&&accounts.value.every(item=>isSelected(item.accountId)))
const unknown=(v:unknown)=>v===null||v===undefined||v===''?'—':String(v)
const statusLabel=(v?:string)=>({CONNECTED:'正常',DEGRADED:'波动',EXPIRED:'已过期',DISCONNECTED:'离线',UNKNOWN:'待检测',AUTHORIZED:'已授权',REVOKED:'已撤销',FULL:'完整',PARTIAL:'部分',UNSYNCED:'未同步',CRITICAL:'严重',HIGH:'高',WARNING:'提醒',INFO:'信息'}[v||'']||v||'未知')
const tone=(v?:string)=>['CONNECTED','AUTHORIZED','FULL'].includes(v||'')?'good':['CRITICAL','HIGH','EXPIRED','DISCONNECTED','REVOKED'].includes(v||'')?'bad':['DEGRADED','WARNING','PARTIAL'].includes(v||'')?'warn':'muted'
const formatTime=(v?:string)=>v?new Date(v).toLocaleString('zh-CN'):'—'
const load=async()=>{loading.value=true;try{const [a,all,s,g]=await Promise.all([queryAccountMatrix({...filter,page:page.value,pageSize:20}),queryAccountMatrix({page:1,pageSize:100}),getAccountMatrixSummary(),getAccountGroups()]);accounts.value=a.data?.records||[];allAccounts.value=all.data?.records||[];total.value=a.data?.total||0;summary.value=s.data||null;groups.value=g.data||[]}catch(e:any){showError(e.message||'账号矩阵加载失败')}finally{loading.value=false}}
const openDetail=async(account:MatrixAccount)=>{if(selected.value&&selected.value.accountId!==account.accountId)cancelProfilePolling();selected.value=account;detailLoading.value=true;await router.replace({query:{...route.query,accountId:String(account.accountId)}});try{const res=await getAccountMatrixDetail(account.accountId);selected.value=res.data||account}catch(e:any){showError(e.message||'账号详情加载失败')}finally{detailLoading.value=false}}
const syncProfile=async(account:MatrixAccount)=>{if(profileSyncing.value)return;const run=++profileSyncRun;profileSyncing.value=true;const requestId=newRequestId('profile');try{const accepted=await syncAccountProfile(account.accountId,requestId);if(run!==profileSyncRun)return;if(accepted.data?.status!=='RUNNING')throw new Error(accepted.data?.status==='BUSY'?'该账号已有画像同步任务，请稍后查看':'画像同步未被服务器接受');for(let attempt=0;attempt<60;attempt++){await new Promise(resolve=>setTimeout(resolve,1000));if(run!==profileSyncRun)return;const state=await getAccountProfileSync(account.accountId,requestId);if(run!==profileSyncRun)return;if(state.data?.status==='SUCCEEDED'){showSuccess('店铺画像已从闲鱼只读接口更新');await openDetail(account);await load();return}if(state.data?.status==='FAILED')throw new Error(`${state.data.errorMessage||'店铺画像同步失败'}${state.data.recoveryHint?`；${state.data.recoveryHint}`:''}`)}throw new Error('画像同步仍在进行，可稍后重新打开查看状态')}catch(e:any){if(run!==profileSyncRun)return;showError(e.message||'店铺画像同步失败');if(selected.value?.accountId===account.accountId){const res=await getAccountMatrixDetail(account.accountId).catch(()=>null);if(res?.data)selected.value=res.data}}finally{if(run===profileSyncRun)profileSyncing.value=false}}
const syncRisks=async(account:MatrixAccount)=>{if(riskSyncing.value)return;riskSyncing.value=true;try{const result=await syncAccountRisks(account.accountId,newRequestId('risk'));if(result.data?.status==='FAILED')throw new Error(result.data.errorMessage||'处罚记录同步失败');showSuccess(`处罚记录已同步${result.data?.recordCount===undefined?'':`，共 ${result.data.recordCount} 条`}`);await openDetail(account);await load()}catch(e:any){showError(e.message||'处罚记录同步失败');const detail=await getAccountMatrixDetail(account.accountId).catch(()=>null);if(detail?.data)selected.value=detail.data}finally{riskSyncing.value=false}}
const exportRisks=async(account:MatrixAccount)=>{try{const response=await exportAccountRisks(account.accountId);const url=URL.createObjectURL(response.data as Blob);const anchor=document.createElement('a');anchor.href=url;anchor.download=`account-${account.accountId}-risks.csv`;anchor.click();URL.revokeObjectURL(url)}catch(e:any){showError(e.message||'处罚记录导出失败')}}
const closeDetail=()=>{cancelProfilePolling();selected.value=null;void router.replace({query:{...route.query,accountId:undefined}})}
const clearSelection=()=>{selectionMode.value='EXPLICIT';selectedIds.value=[];excludedIds.value=[]}
const apply=()=>{clearSelection();page.value=1;void load()}
const isSelected=(accountId:number)=>selectionMode.value==='FILTER_SNAPSHOT'?!excludedIds.value.includes(accountId):selectedIds.value.includes(accountId)
const toggleAccount=(accountId:number,checked:boolean)=>{if(selectionMode.value==='FILTER_SNAPSHOT'){excludedIds.value=checked?excludedIds.value.filter(id=>id!==accountId):[...new Set([...excludedIds.value,accountId])]}else{selectedIds.value=checked?[...new Set([...selectedIds.value,accountId])]:selectedIds.value.filter(id=>id!==accountId)}}
const togglePage=(checked:boolean)=>{for(const item of accounts.value)toggleAccount(item.accountId,checked)}
const selectFiltered=()=>{selectionMode.value='FILTER_SNAPSHOT';selectedIds.value=[];excludedIds.value=[]}
const openGroup=(g?:AccountGroup)=>{groupForm.id=g?.id;groupForm.groupName=g?.groupName||'';groupForm.color=g?.color||'#ffda44';groupForm.description=g?.description||'';groupForm.accountIds=(g?.accountIdsCsv||'').split(',').map(Number).filter(Boolean);groupDialog.value=true}
const saveGroup=async()=>{if(!groupForm.groupName.trim())return showError('请输入分组名称');groupSaving.value=true;try{const saved=await saveAccountGroup({...groupForm,requestId:newRequestId('group')});if(saved.data?.id)await replaceAccountGroupMembers(saved.data.id,groupForm.accountIds,newRequestId('group-members'));groupDialog.value=false;showSuccess('店铺分组已保存');await load()}finally{groupSaving.value=false}}
onMounted(async()=>{await load();const id=Number(route.query.accountId);const item=accounts.value.find(a=>a.accountId===id);if(item)await openDetail(item)})
onBeforeUnmount(cancelProfilePolling)
</script>

<template>
  <main class="workbench account-matrix" :aria-busy="loading">
    <header class="workbench__header"><div><h1>账号矩阵</h1><p>统一查看连接、授权、店铺画像、风险证据和分组范围。</p></div><div class="workbench__actions"><button class="workbench__btn" :disabled="selectionCount===0" @click="showBatch=true">批量操作</button><button class="workbench__btn" :disabled="!hasPermission('action:account-write')" @click="openGroup()">新建分组</button><button class="workbench__btn" :disabled="!hasPermission('action:credential-write')" @click="showManual=true">手动接入</button><button class="workbench__btn workbench__btn--primary" :disabled="!hasPermission('action:credential-write')" @click="showQr=true">扫码接入</button></div></header>
    <section class="account-matrix__metrics" aria-label="账号概览"><article><span>可见店铺</span><strong>{{ summary?.accountCount ?? '—' }}</strong><small>按成员授权范围</small></article><article><span>连接正常</span><strong>{{ summary?.connectedCount ?? '—' }}</strong><small>通道最近检测</small></article><article><span>需要关注</span><strong>{{ summary?.attentionAccountCount ?? '—' }}</strong><small>高风险或严重风险</small></article><article><span>画像未同步</span><strong>{{ summary?.unsyncedProfileCount ?? '—' }}</strong><small>不以 0 补齐字段</small></article><article><span>已知活跃风险</span><strong>{{ summary?.knownActiveRiskCount ?? '—' }}</strong><small>{{ statusLabel(summary?.riskCoverage) }}</small></article></section>
    <div class="account-matrix__notice"><strong>数据边界</strong><span>店铺画像和处罚以最近一次同步快照为准；“—”表示未知或未同步，不代表 0。</span><time>{{ summary?.generatedAt?`生成于 ${formatTime(summary.generatedAt)}`:'等待读取' }}</time></div>
    <div v-if="deleteFeedback" class="account-matrix__delete-feedback" role="status"><span>{{ deleteFeedback }}</span><button aria-label="关闭删除结果提示" @click="deleteFeedback=''">关闭</button></div>
    <section v-if="selectionCount" class="account-matrix__selection"><div><strong>{{ selectionMode==='FILTER_SNAPSHOT'?`已选择当前筛选全部 ${selectionCount} 家店铺`:`已选择 ${selectionCount} 家店铺` }}</strong><span>{{ selectionMode==='FILTER_SNAPSHOT'?'范围将在预检时生成快照；翻页不会丢失选择。':'可继续翻页勾选，选择不会丢失。' }}</span></div><button v-if="selectionMode==='EXPLICIT'&&selectedIds.length<total" @click="selectFiltered">选择当前筛选全部 {{ total }} 家</button><button @click="clearSelection">清空</button><button class="primary" @click="showBatch=true">批量操作</button></section>
    <AccountProfileModal v-if="selected" :account="selected" :loading="detailLoading" :syncing="profileSyncing" :risk-syncing="riskSyncing" @close="closeDetail" @dashboard="router.push({path:'/dashboard',query:{accountId:String(selected.accountId)}})" @refresh="openDetail(selected)" @sync-profile="syncProfile(selected)" @sync-risks="syncRisks(selected)" @export-risks="exportRisks(selected)" />
    <section class="workbench__card account-matrix__panel"><div class="account-matrix__toolbar"><input v-model="filter.search" class="workbench__input" placeholder="搜索账号 ID、备注或店铺名" @keyup.enter="apply"><select v-model="filter.groupId" class="workbench__select" @change="apply"><option :value="undefined">全部分组</option><option v-for="g in groups" :key="g.id" :value="g.id">{{ g.groupName }}（{{ g.accountCount||0 }}）</option></select><select v-model="filter.lifecycleState" class="workbench__select" aria-label="本地账号状态" @change="apply"><option value="">未归档账号</option><option value="ACTIVE">已启用</option><option value="DISABLED">已停用</option><option value="ARCHIVED">已归档</option><option value="ALL">全部本地状态</option></select><select v-model="filter.connectionStatus" class="workbench__select" @change="apply"><option value="">全部连接状态</option><option value="CONNECTED">正常</option><option value="DEGRADED">波动</option><option value="EXPIRED">凭据过期</option><option value="DISCONNECTED">离线</option><option value="UNKNOWN">待检测</option></select><select v-model="filter.riskSeverity" class="workbench__select" @change="apply"><option value="">全部风险</option><option value="CRITICAL">严重</option><option value="HIGH">高</option><option value="WARNING">提醒</option><option value="INFO">信息</option></select><button class="workbench__btn" @click="apply">查询</button></div>
      <div class="account-matrix__groups"><button :class="{active:filter.groupId===undefined}" @click="filter.groupId=undefined;apply()">全部店铺</button><button v-for="g in groups" :key="g.id" :class="{active:filter.groupId===g.id}" @click="filter.groupId=g.id;apply()"><i :style="{background:g.color||'#ffda44'}"></i>{{ g.groupName }}<span>{{ g.accountCount||0 }}</span><em v-if="hasPermission('action:account-write')" @click.stop="openGroup(g)">编辑</em></button></div>
      <div class="account-matrix__table-wrap"><table><thead><tr><th class="account-matrix__check"><input type="checkbox" :checked="pageAllSelected" aria-label="选择当前页" @change="togglePage(($event.target as HTMLInputElement).checked)"></th><th>店铺</th><th>分组</th><th>连接 / 授权</th><th>店铺画像</th><th>风险</th><th>最近证据</th><th>操作</th></tr></thead><tbody><tr v-for="item in accounts" :key="item.accountId" :class="{selected:isSelected(item.accountId)}" @click="openDetail(item)"><td class="account-matrix__check"><input type="checkbox" :checked="isSelected(item.accountId)" :aria-label="`选择账号 ${item.accountId}`" @click.stop @change="toggleAccount(item.accountId,($event.target as HTMLInputElement).checked)"></td><td><strong>{{ item.accountNote||item.shopNickname||`账号 ${item.accountId}` }}</strong><small>ID {{ item.accountId }} · UNB {{ item.unb||'—' }}</small></td><td><div class="tag-row"><span v-for="g in item.groups" :key="g.id" class="mini-tag"><i :style="{background:g.color||'#ffda44'}"></i>{{ g.groupName }}</span><span v-if="!item.groups.length" class="muted">未分组</span></div></td><td><span :class="['status',tone(item.connectionStatus)]">{{ statusLabel(item.connectionStatus) }}</span><small>{{ statusLabel(item.authorizationStatus) }} · {{ item.credentialExpireTime?formatTime(item.credentialExpireTime):'到期未知' }}</small><small>{{ item.connectionSource==='LOCAL_RUNTIME'?'运行时实测':item.connectionSource||'来源未记录' }} · {{ formatTime(item.connectionLastCheckedTime) }}</small></td><td><strong>{{ unknown(item.shopNickname) }}</strong><small>{{ statusLabel(item.profileCoverageStatus) }} · {{ item.profileSource==='NONE'?'无来源':item.profileSource }}</small></td><td><span :class="['status',tone(item.highestRiskSeverity)]">{{ item.highestRiskSeverity?statusLabel(item.highestRiskSeverity):item.riskCoverageStatus==='UNSYNCED'?'未同步':'无活跃风险' }}</span><small>数量 {{ item.knownActiveRiskCount ?? '—' }}</small></td><td><small>{{ formatTime(item.connectionLastCheckedTime||item.profileSyncedAt||item.riskSyncedAt) }}</small></td><td><div class="account-matrix__row-actions"><button class="row-action" @click.stop="openDetail(item)">查看详情</button><button class="row-action" :disabled="!hasPermission('action:account-write')" @click.stop="editTarget=item;showEdit=true">编辑本地设置</button><button class="row-action" @click.stop="lifecycleTarget=item">{{ item.lifecycleState==='ARCHIVED'?'归档状态':item.lifecycleState==='DISABLED'?'停用状态':'本地状态' }}</button><button v-if="hasPermission('action:account-delete')" class="row-action row-action--danger" :aria-label="`删除账号 ${item.accountNote||item.accountId}`" @click.stop="openDelete(item)">删除账号</button></div></td></tr></tbody></table><div v-if="!loading&&!accounts.length" class="account-matrix__empty">当前筛选范围没有账号。</div></div><footer class="account-matrix__pagination"><span>共 {{ total }} 个店铺</span><div><button :disabled="page<=1" @click="page--;load()">上一页</button><b>{{ page }} / {{ totalPages }}</b><button :disabled="page>=totalPages" @click="page++;load()">下一页</button></div></footer></section>
    <DeleteConfirmDialog :model-value="Boolean(deleteTarget)" :account-id="deleteTarget?.accountId" @update:model-value="value=>{if(!value)deleteTarget=null}" @success="deleted" />
    <div v-if="groupDialog" class="modal-backdrop" @click.self="groupDialog=false"><section class="modal-card" role="dialog" aria-modal="true" aria-labelledby="group-title"><header><div><h2 id="group-title">{{ groupForm.id?'编辑分组':'新建分组' }}</h2><p>分组用于筛选、成员授权和通知范围，不会移动或删除店铺。</p></div><button aria-label="关闭" @click="groupDialog=false">×</button></header><label>分组名称<input v-model="groupForm.groupName" class="workbench__input" maxlength="100"></label><label>说明<textarea v-model="groupForm.description" class="workbench__textarea" maxlength="500"></textarea></label><fieldset><legend>包含店铺</legend><label v-for="a in allAccounts" :key="a.accountId"><input v-model="groupForm.accountIds" type="checkbox" :value="a.accountId"><span>{{ a.accountNote||a.shopNickname||`账号 ${a.accountId}` }}</span></label></fieldset><footer><button class="workbench__btn" @click="groupDialog=false">取消</button><button class="workbench__btn workbench__btn--primary" :disabled="groupSaving" @click="saveGroup">保存分组</button></footer></section></div>
    <AccountBatchDialog v-model="showBatch" :selection-mode="selectionMode" :account-ids="selectedIds" :excluded-account-ids="excludedIds" :filter="filter" @completed="load"/>
    <AccountLifecycleDialog :model-value="Boolean(lifecycleTarget)" :account-id="lifecycleTarget?.accountId" @update:model-value="value=>{if(!value)lifecycleTarget=null}" @success="load" />
    <QRLoginDialog v-model="showQr" @success="load"/><ManualAddDialog v-model="showManual" @success="load"/><AddAccountDialog v-model="showEdit" :account="editTarget?({id:editTarget.accountId,accountNote:editTarget.accountNote,unb:editTarget.unb} as any):null" @success="load"/>
  </main>
</template>
<style scoped src="./accounts.css"></style>
<style scoped>
@media (max-width: 767px) {
  .account-matrix__metrics { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); overflow: visible; scroll-snap-type: none; }
  .account-matrix__metrics article { min-width: 0; }
}
</style>
